// LLMConfig 控制 Manifest 智慧增強的 LLM 層
type LLMConfig struct {
	// Mode 控制 LLM 增強模式
	// "none"（預設）：不使用 LLM，只做純 Go 推斷（零成本）
	// "ollama"：直接連接本地 Ollama 伺服器
	// "api"：連接遠端 API（OpenAI、Anthropic、Gemini 等）
	Mode string `yaml:"mode"`

	// Ollama 模式配置（mode=ollama 時使用）
	Ollama OllamaConfig `yaml:"ollama"`

	// API 模式配置（mode=api 時使用）
	API APIConfig `yaml:"api"`
}

// OllamaConfig 本地 Ollama 模式配置
type OllamaConfig struct {
	URL       string `yaml:"url"`        // Ollama API URL（預設 http://localhost:11434）
	Model     string `yaml:"model"`      // 模型名稱 e.g. "llama3", "codellama", "mistral"
	Timeout   int    `yaml:"timeout"`    // 請求逾時秒數（預設 30）
	MaxTokens int    `yaml:"max_tokens"` // 最大回應 token 數（預設 256）
}

// APIConfig 遠端 API 模式配置
type APIConfig struct {
	Provider  string `yaml:"provider"`   // "openai", "anthropic", "gemini", "custom"
	BaseURL   string `yaml:"base_url"`   // API 端點（custom 時必填；其他 provider 有預設值）
	APIKey    string `yaml:"api_key"`    // API 金鑰（支援 ${ENV_VAR} 環境變數展開）
	Model     string `yaml:"model"`      // 模型名稱 e.g. "gpt-4o-mini", "claude-haiku-4-5"
	Timeout   int    `yaml:"timeout"`    // 請求逾時秒數（預設 30）
	MaxTokens int    `yaml:"max_tokens"` // 最大回應 token（預設 256）
}

// ApplyDefaults 為 LLMConfig 填入預設值
func (c *LLMConfig) ApplyDefaults() {
	if c.Mode == "" {
		c.Mode = "none"
	}

	// Ollama 預設值
	if c.Ollama.URL == "" {
		c.Ollama.URL = "http://localhost:11434"
	}
	if c.Ollama.Timeout == 0 {
		c.Ollama.Timeout = 30
	}
	if c.Ollama.MaxTokens == 0 {
		c.Ollama.MaxTokens = 256
	}

	// API 預設值
	if c.API.Timeout == 0 {
		c.API.Timeout = 30
	}
	if c.API.MaxTokens == 0 {
		c.API.MaxTokens = 256
	}
	// Provider 預設 BaseURL
	if c.API.BaseURL == "" {
		switch c.API.Provider {
		case "openai":
			c.API.BaseURL = "https://api.openai.com/v1"
		case "anthropic":
			c.API.BaseURL = "https://api.anthropic.com/v1"
		case "gemini":
			c.API.BaseURL = geminiOpenAIBaseURL
		}
	}
	// Gemini 的 OpenAI 相容端點在 .../v1beta/openai。先前預設值少了 /openai：
	// pkg/annotation 自己補上了，pkg/manifest 的 LLM 增強卻直接接 /chat/completions 而必定失敗
	if strings.EqualFold(c.API.Provider, "gemini") && strings.TrimRight(c.API.BaseURL, "/") == strings.TrimSuffix(geminiOpenAIBaseURL, "/openai") {
		c.API.BaseURL = geminiOpenAIBaseURL
	}
}

const geminiOpenAIBaseURL = "https://generativelanguage.googleapis.com/v1beta/openai"

// Validate 驗證 LLMConfig 的邏輯正確性
func (c *LLMConfig) Validate() error {
	switch c.Mode {
	case "none":
		return nil

	case "ollama":
		if c.Ollama.Model == "" {
			return fmt.Errorf("llm.ollama.model is required when mode=ollama")
		}

	case "api":
		if c.API.Provider == "" {
			return fmt.Errorf("llm.api.provider is required when mode=api")
		}
		// 不限制 provider 名稱：openai / anthropic / gemini 有內建預設 BaseURL；
		// 其他名稱（含 custom、本地推論伺服器、第三方相容端點）一律需提供 base_url。
		if !hasBuiltinBaseURL(c.API.Provider) && c.API.BaseURL == "" {
			return fmt.Errorf("llm.api.base_url is required when provider=%q (only openai/anthropic/gemini have built-in defaults)", c.API.Provider)
		}
		if c.API.Model == "" {
			return fmt.Errorf("llm.api.model is required when mode=api")
		}
		// API key 可透過環境變數設定，所以允許為空（但展開後不可為空）
		resolved := c.API.ResolvedAPIKey()
		if resolved == "" {
			return fmt.Errorf("llm.api.api_key is required when mode=api (supports ${ENV_VAR} syntax)")
		}

	default:
		return fmt.Errorf("llm.mode must be one of: none, ollama, api; got %q", c.Mode)
	}

	return nil
}

// hasBuiltinBaseURL 回傳 provider 是否有內建預設 BaseURL（ApplyDefaults 會自動填）
func hasBuiltinBaseURL(provider string) bool {
	switch provider {
	case "openai", "anthropic", "gemini":
		return true
	}
	return false
}

// ResolvedAPIKey 展開 API key 中的環境變數引用
// 支援 ${ENV_VAR} 語法
func (c *APIConfig) ResolvedAPIKey() string {
	return expandEnvVars(c.APIKey)
}

// expandEnvVars 展開字串中的 ${ENV_VAR} 引用
func expandEnvVars(s string) string {
	// 只展開 ${NAME}。先前用 os.Expand：字串裡有 ${ 時，其他的 $abc 也被當成環境變數而被吃掉
	return envRef.ReplaceAllStringFunc(s, func(ref string) string {
		return os.Getenv(ref[2 : len(ref)-1])
	})
}

var envRef = regexp.MustCompile(`\$\{[A-Za-z_][A-Za-z0-9_]*\}`)

// IsEnabled 回傳 LLM 增強是否啟用
func (c *LLMConfig) IsEnabled() bool {
	return c.Mode != "" && c.Mode != "none"
}

// LoadLLMConfig 從指定路徑載入 LLM 配置
